CREATE TABLE "a" (
  "id" int PRIMARY KEY,
  "b_id" int NOT NULL,
  "n" int
);

CREATE TABLE "b" (
  "id" int PRIMARY KEY,
  "u" int UNIQUE
);

ALTER TABLE "a" ADD FOREIGN KEY ("b_id") REFERENCES "b" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "a" ADD CONSTRAINT "r2" FOREIGN KEY ("n") REFERENCES "b" ("u") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
